    el("h2", {}, "Proposals"),
    notes,
    proposals.length ? el("table", {},
      el("thead", {}, el("tr", {}, ["Cluster", "Template", "From", "Proposed", "Rationale", ""]
        .map((h) => el("th", {}, h)))),
      el("tbody", {}, rows.flat()))
      : el("p", { class: "muted" }, "Nothing waiting for review."),
